const CACHE_NAME="reverie-pwa-v41",PAGE_CACHE_NAME="reverie-pages-v41",STATIC_ASSETS=["/","/search","/entities","/uploads","/account","/privacy","/account-deletion","/tasks","/recommendations","/static/manifest.json","/static/reverie-home.min.css","/static/reverie-home.min.js","/static/reverie-list-page.min.css","/static/reverie-list-page.min.js","/static/reverie-search.min.js","/static/reverie-entities.min.js","/static/reverie-uploads.min.js","/static/reverie-capture.min.js","/static/reverie-shared.min.js","/static/reverie-notifications.min.js","/static/logo_reverie.webp","/static/icon-192.png","/static/icon-512.png"];self.addEventListener("install",i=>{i.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(STATIC_ASSETS)).catch(()=>{})),self.skipWaiting()}),self.addEventListener("activate",i=>{i.waitUntil(caches.keys().then(e=>Promise.all(e.filter(s=>![CACHE_NAME,PAGE_CACHE_NAME].includes(s)).map(s=>caches.delete(s))))),self.clients.claim()}),self.addEventListener("fetch",i=>{const e=i.request;if(e.method!=="GET")return;const s=new URL(e.url);if(e.headers.get("X-Reverie-App-Shell")==="1"){i.respondWith(fetch(e));return}if(e.mode==="navigate"){i.respondWith(caches.open(PAGE_CACHE_NAME).then(n=>fetch(e).then(t=>(t.ok&&n.put(e,t.clone()),t)).catch(()=>n.match(e).then(t=>t||caches.match("/")||Response.error()))));return}s.origin!==self.location.origin||!s.pathname.startsWith("/static/")||i.respondWith(caches.match(e).then(n=>n||fetch(e).then(t=>{if(t.ok){const c=t.clone();caches.open(CACHE_NAME).then(r=>r.put(e,c))}return t})))});
